import React, { useState } from 'react';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import PasswordInput from '../../components/common/PasswordInput/PasswordInput';
import ToggleButton from '../../components/common/ToggleButton/ToggleButton';
import styles from './RegisterPage.module.css';

const RegisterPage = () => {
    const [selectedLevel, setSelectedLevel] = useState('D2');
    const levels = ['D1', 'D2', 'D3', 'D4', 'D4+'];

    return (
        <div className={styles.registerPage}>
            <div className={styles.container}>
                <div className={styles.registerCard}>
                    <div className={styles.header}>
                        <img src="/assets/images/logo_t.png" alt="Volley Hub" className={styles.logo} />
                        <h1 className={styles.title}>Регистрация</h1>
                        <p className={styles.subtitle}>Создайте новый аккаунт</p>
                    </div>

                    <form className={styles.form}>
                        <Input
                            label="Имя"
                            placeholder="Введите ваше имя"
                            required
                        />

                        <Input
                            label="Email"
                            type="email"
                            placeholder="Введите ваш email"
                            required
                        />

                        <Input
                            label="Телефон"
                            placeholder="+375 XX XXX-XX-XX"
                        />

                        <div className={styles.levelSection}>
                            <label className={styles.label}>Уровень игры *</label>
                            <div className={styles.levelButtons}>
                                {levels.map(level => (
                                    <ToggleButton
                                        key={level}
                                        label={level}
                                        isActive={selectedLevel === level}
                                        onClick={() => setSelectedLevel(level)}
                                    />
                                ))}
                            </div>
                        </div>

                        <PasswordInput label="Пароль" placeholder="Введите пароль" />
                        <PasswordInput label="Подтверждение пароля" placeholder="Подтвердите пароль" />

                        <Button type="submit" fullWidth size="large">
                            Зарегистрироваться
                        </Button>
                    </form>

                    <div className={styles.footer}>
                        <p className={styles.loginLink}>
                            Уже есть аккаунт? <a href="/login">Войти</a>
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default RegisterPage;
